#!/usr/bin/env python3
"""Pure MainFence bridge control entry. No live Main or Android access."""
import base64,hashlib,json,signal,sys,time,types
PACKET_SHA="75004c37610508289ee2173735b1d4bd37d80543baa9699e2406dcf5c4d32677"
PACKET_BASE64=""
def need(value,code):
    if not value:raise RuntimeError(code)
def alarm(signum,frame):
    raise TimeoutError("PURE_MAIN_BRIDGE_CONTROL_DEADLINE")
def main():
    result={"schema":"owner20-current-main-bridge-control-result-v1","success":False,"errors":[],
            "Main_accessed":False,"Android_commands":0,"process_children":0,
            "private_baseline_body_used":False,"current_Main_runtime_qualified":False}
    owned_alarm=False;old_handler=None;started=time.monotonic_ns()
    def error(stage,e):
        row={"stage":stage,"type":type(e).__name__,"message":str(e)[:1000]}
        result["errors"].append(row)
        if "first_error" not in result:result["first_error"]=row
    try:
        need(signal.getitimer(signal.ITIMER_REAL)==(0.0,0.0),"PREEXISTING_TIMER")
        old_handler=signal.getsignal(signal.SIGALRM)
        signal.signal(signal.SIGALRM,alarm);owned_alarm=True
        signal.setitimer(signal.ITIMER_REAL,15.0)
        raw=base64.b64decode(PACKET_BASE64,validate=True)
        need(hashlib.sha256(raw).hexdigest()==PACKET_SHA,"FIXED_PACKET_SHA")
        packet=json.loads(raw)
        need(packet["schema"]==1 and packet["kind"]=="owner20-current-main-bridge-pure-controls01" and
             set(packet["members"])=={"candidate.py","baseline.py","controls.py","historical-main.json"},
             "FIXED_PACKET_SCHEMA")
        texts={};pins={}
        for name,row in packet["members"].items():
            need(set(row)=={"text","bytes","sha256"},"MEMBER_SCHEMA")
            body=row["text"].encode()
            need(len(body)==row["bytes"] and hashlib.sha256(body).hexdigest()==row["sha256"],"MEMBER_PIN")
            if name.endswith(".py"):compile(body,name,"exec")
            texts[name]=row["text"];pins[name]={"bytes":row["bytes"],"sha256":row["sha256"]}
        result["source_pins"]=pins
        mod=types.ModuleType("owner20_main_bridge_pure_controls")
        exec(compile(texts["controls.py"],"controls.py","exec"),mod.__dict__)
        result["controls"]=mod.run(texts["candidate.py"],texts["baseline.py"],json.loads(texts["historical-main.json"]))
        need(result["controls"]["passed"] is True and result["controls"]["count"]==12,"ALL_12_CONTROLS_REQUIRED")
    except BaseException as e:error("pure_controls",e)
    finally:
        if owned_alarm:
            try:signal.setitimer(signal.ITIMER_REAL,0,0)
            except BaseException as e:error("timer_disarm",e)
            try:signal.signal(signal.SIGALRM,old_handler)
            except BaseException as e:error("handler_restore",e)
    result["elapsed_ns"]=time.monotonic_ns()-started
    result["success"]=not result["errors"] and result.get("controls",{}).get("passed") is True
    raw=(json.dumps(result,sort_keys=True,separators=(",",":"))+"\n").encode()
    need(len(raw)<=16384,"PURE_CONTROL_OUTPUT_BOUND")
    sys.stdout.buffer.write(raw);sys.stdout.buffer.flush()
    return 0 if result["success"] else 1
if __name__=="__main__":raise SystemExit(main())
